corrected_code:
const express = require('express');
const { body, validationResult } = require('express-validator');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();
app.use(express.json());

const directDepositValidation = [
  body('routingNumber').isNumeric().isLength({ min: 9, max: 9 }).withMessage('Routing number must be 9 digits'),
  body('accountNumber').isString().isLength({ min: 6, max: 17 }).withMessage('Account number length invalid')
];

app.put('/api/hr/direct-deposit', directDepositValidation, async (req, res) => {
  if (!req.user || !req.user.employeeId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Derive employee ID strictly from the authenticated session
  const employeeId = req.user.employeeId;
  const { routingNumber, accountNumber } = req.body;

  const record = await prisma.directDeposit.upsert({
    where: { employeeId },
    update: { routingNumber, accountNumber, updatedAt: new Date() },
    create: { employeeId, routingNumber, accountNumber }
  });

  res.json({ success: true, recordId: record.id });
});

app.listen(6001);
